/**
 * TCG cache schema: Pokémon + Magic: The Gathering + Riftbound
 * Sources: JustTCG (condition-level prices) and TCG API (catalog, images, sales volume)
 *
 * Column names are camelCase in TS and snake_case in Postgres (see `casing` in
 * drizzle.config.ts and db/index.ts).
 *
 * Better Auth's tables (user, session, account, verification) are generated by
 * its CLI and live in their own file; the collection tracker will reference `user.id`.
 */
import { relations, sql } from "drizzle-orm";
import {
  check,
  date,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  primaryKey,
  real,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from "drizzle-orm/pg-core";

// ────────────────────────────────────────────────────────────────────────────
// Shared
// ────────────────────────────────────────────────────────────────────────────

export const apiSource = pgEnum("api_source", ["justtcg", "tcgapi"]);

/** Normalized from "Near Mint" / "NM" / "near-mint", etc. */
export const cardCondition = pgEnum("card_condition", ["NM", "LP", "MP", "HP", "DMG"]);

const timestamps = {
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp({ withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

// ────────────────────────────────────────────────────────────────────────────
// Catalog
// ────────────────────────────────────────────────────────────────────────────

/** Our own slugs ('pokemon', 'mtg', 'riftbound'), mapped to each API's game identifier. */
export const game = pgTable("game", {
  id: text().primaryKey(),
  name: text().notNull(),
  justtcgGameId: text().unique(),
  tcgapiGameSlug: text().unique(),
  ...timestamps,
});

export const cardSet = pgTable(
  "card_set",
  {
    id: uuid().primaryKey().defaultRandom(),
    gameId: text()
      .notNull()
      .references(() => game.id),
    name: text().notNull(),
    /** TCG API `abbreviation`, e.g. "SV08" / "MH3" */
    code: text(),
    releaseDate: date(),
    cardCount: integer(),

    // Each API's own set ID. Sets are matched across sources through their
    // cards' shared TCGplayer product IDs, not by name.
    justtcgSetId: text(),
    tcgapiSetId: text(),

    ...timestamps,
  },
  (t) => [
    uniqueIndex("card_set_justtcg_uq").on(t.justtcgSetId),
    uniqueIndex("card_set_tcgapi_uq").on(t.tcgapiSetId),
    index("card_set_game_release_idx").on(t.gameId, t.releaseDate),
  ],
);

/**
 * One row per card product (one TCGplayer product).
 * `tcgplayerProductId` is the join key: JustTCG exposes it as `tcgplayerId`,
 * TCG API as `tcgplayer_id`.
 */
export const card = pgTable(
  "card",
  {
    id: uuid().primaryKey().defaultRandom(),
    gameId: text()
      .notNull()
      .references(() => game.id),
    setId: uuid()
      .notNull()
      .references(() => cardSet.id),

    name: text().notNull(),
    number: text(), // text on purpose: "4/102", "TG01", "123a"
    rarity: text(),
    imageUrl: text(),

    // Cross-source identifiers
    tcgplayerProductId: text(),
    justtcgCardId: text(), // JustTCG v1 `uuid` (v2 `id`)
    tcgapiCardId: text(),
    scryfallId: uuid(), // MTG only
    mtgjsonId: uuid(), // MTG only

    /** Game-specific extras (HP, types, TCG API custom_attributes, JustTCG details) */
    attributes: jsonb().$type<Record<string, unknown>>(),

    // Freshness for each source; the sync job refreshes the stalest tracked cards first.
    justtcgPricesFetchedAt: timestamp({ withTimezone: true }),
    tcgapiPricesFetchedAt: timestamp({ withTimezone: true }),

    ...timestamps,
  },
  (t) => [
    uniqueIndex("card_tcgplayer_uq").on(t.tcgplayerProductId),
    uniqueIndex("card_justtcg_uq").on(t.justtcgCardId),
    uniqueIndex("card_tcgapi_uq").on(t.tcgapiCardId),
    index("card_set_number_idx").on(t.setId, t.number),
    index("card_scryfall_idx").on(t.scryfallId),
    // Fuzzy name search over the cache. Requires `CREATE EXTENSION pg_trgm` (see migrations note).
    index("card_name_trgm_idx").using("gin", sql`${t.name} gin_trgm_ops`),
  ],
);

/**
 * A specific copy a person could own: printing × condition × language.
 * Collection items will point here.
 */
export const cardVariant = pgTable(
  "card_variant",
  {
    id: uuid().primaryKey().defaultRandom(),
    cardId: uuid()
      .notNull()
      .references(() => card.id, { onDelete: "cascade" }),

    printing: text().notNull(), // "Normal", "Foil", "Holofoil", "Reverse Holofoil", "1st Edition"…
    condition: cardCondition().notNull(),
    language: text().notNull().default("English"), // JustTCG omits language for English

    justtcgVariantId: text(), // JustTCG v1 variant `uuid`
    tcgplayerSkuId: text(),

    ...timestamps,
  },
  (t) => [
    uniqueIndex("card_variant_natural_uq").on(t.cardId, t.printing, t.condition, t.language),
    uniqueIndex("card_variant_justtcg_uq").on(t.justtcgVariantId),
    uniqueIndex("card_variant_sku_uq").on(t.tcgplayerSkuId),
  ],
);

// ────────────────────────────────────────────────────────────────────────────
// Prices
// Money is stored as integer cents (USD): exact, compact, no float rounding.
// The two sources price at different levels, so each gets its own tables
// instead of a lowest-common-denominator table full of NULLs.
// ────────────────────────────────────────────────────────────────────────────

/** JustTCG, latest known price for each variant. Upserted on every fetch. */
export const variantPriceCurrent = pgTable("variant_price_current", {
  variantId: uuid()
    .primaryKey()
    .references(() => cardVariant.id, { onDelete: "cascade" }),
  priceCents: integer(),
  priceStatus: text().$type<"current" | "expired" | "unpriced">(),
  lastKnownPriceCents: integer(),
  change24hPct: real(),
  change7dPct: real(),
  change30dPct: real(),
  change90dPct: real(),
  /** JustTCG `lastUpdated`: when the source observed the price */
  observedAt: timestamp({ withTimezone: true }),
  /** When we fetched it */
  fetchedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
});

/** JustTCG, one row per variant per day: our own history, built from daily snapshots. */
export const variantPriceDaily = pgTable(
  "variant_price_daily",
  {
    variantId: uuid()
      .notNull()
      .references(() => cardVariant.id, { onDelete: "cascade" }),
    day: date().notNull(),
    priceCents: integer().notNull(),
  },
  (t) => [primaryKey({ columns: [t.variantId, t.day] })],
);

/** TCG API, prices for each printing (no condition split on lower tiers). Latest only. */
export const printingPriceCurrent = pgTable(
  "printing_price_current",
  {
    cardId: uuid()
      .notNull()
      .references(() => card.id, { onDelete: "cascade" }),
    printing: text().notNull(),
    marketCents: integer(),
    lowCents: integer(),
    medianCents: integer(),
    lowestWithShippingCents: integer(),
    buylistCents: integer(),
    totalListings: integer(),
    change24hPct: real(),
    change7dPct: real(),
    change30dPct: real(),
    /** TCG API `market_price_as_of` */
    marketAsOf: date(),
    fetchedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [primaryKey({ columns: [t.cardId, t.printing] })],
);

/** TCG API, daily history for each printing, including sales volume (from /cards/:id/history). */
export const printingPriceDaily = pgTable(
  "printing_price_daily",
  {
    cardId: uuid()
      .notNull()
      .references(() => card.id, { onDelete: "cascade" }),
    printing: text().notNull(),
    day: date().notNull(),
    marketCents: integer(),
    lowCents: integer(),
    avgSalesCents: integer(),
    /** NULL = not reported yet (newest 1–3 days); 0 = no sales that day */
    salesVolume: integer(),
  },
  (t) => [primaryKey({ columns: [t.cardId, t.printing, t.day] })],
);

// ────────────────────────────────────────────────────────────────────────────
// Sync bookkeeping. The free tiers allow about 100 requests/day per source, so we track every call.
// ────────────────────────────────────────────────────────────────────────────

/** Atomic counter per source per day; check it before each outbound call. */
export const apiUsageDaily = pgTable(
  "api_usage_daily",
  {
    source: apiSource().notNull(),
    day: date().notNull(),
    requests: integer().notNull().default(0),
    /** Last remaining-quota value the API reported, if any */
    reportedRemaining: integer(),
  },
  (t) => [
    primaryKey({ columns: [t.source, t.day] }),
    check("api_usage_requests_nonneg", sql`${t.requests} >= 0`),
  ],
);

export const syncStatus = pgEnum("sync_status", ["running", "succeeded", "failed", "partial"]);

/** One row per job execution (e.g. "catalog:sets", "catalog:set-cards", "prices:tracked"). */
export const syncRun = pgTable(
  "sync_run",
  {
    id: uuid().primaryKey().defaultRandom(),
    source: apiSource().notNull(),
    job: text().notNull(),
    status: syncStatus().notNull().default("running"),
    startedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
    finishedAt: timestamp({ withTimezone: true }),
    requestsUsed: integer().notNull().default(0),
    rowsUpserted: integer().notNull().default(0),
    /** Where to resume a paginated job tomorrow, e.g. { setId, page } */
    cursor: jsonb().$type<Record<string, unknown>>(),
    error: text(),
  },
  (t) => [index("sync_run_job_started_idx").on(t.source, t.job, t.startedAt)],
);

/**
 * Read-through cache of raw API responses (searches, set listings).
 * Key = hash of source + method + path + sorted query/body.
 * Normalized tables above stay the source of truth; this table only saves API quota.
 */
export const apiResponseCache = pgTable(
  "api_response_cache",
  {
    key: text().primaryKey(),
    source: apiSource().notNull(),
    endpoint: text().notNull(),
    statusCode: integer().notNull(),
    body: jsonb().notNull(),
    fetchedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp({ withTimezone: true }).notNull(),
  },
  (t) => [index("api_response_cache_expires_idx").on(t.expiresAt)],
);

// ────────────────────────────────────────────────────────────────────────────
// Relations (for db.query.*)
// ────────────────────────────────────────────────────────────────────────────

export const gameRelations = relations(game, ({ many }) => ({
  sets: many(cardSet),
  cards: many(card),
}));

export const cardSetRelations = relations(cardSet, ({ one, many }) => ({
  game: one(game, { fields: [cardSet.gameId], references: [game.id] }),
  cards: many(card),
}));

export const cardRelations = relations(card, ({ one, many }) => ({
  game: one(game, { fields: [card.gameId], references: [game.id] }),
  set: one(cardSet, { fields: [card.setId], references: [cardSet.id] }),
  variants: many(cardVariant),
  printingPrices: many(printingPriceCurrent),
}));

export const cardVariantRelations = relations(cardVariant, ({ one, many }) => ({
  card: one(card, { fields: [cardVariant.cardId], references: [card.id] }),
  currentPrice: one(variantPriceCurrent, {
    fields: [cardVariant.id],
    references: [variantPriceCurrent.variantId],
  }),
  history: many(variantPriceDaily),
}));

export const variantPriceCurrentRelations = relations(variantPriceCurrent, ({ one }) => ({
  variant: one(cardVariant, {
    fields: [variantPriceCurrent.variantId],
    references: [cardVariant.id],
  }),
}));

export const variantPriceDailyRelations = relations(variantPriceDaily, ({ one }) => ({
  variant: one(cardVariant, {
    fields: [variantPriceDaily.variantId],
    references: [cardVariant.id],
  }),
}));

export const printingPriceCurrentRelations = relations(printingPriceCurrent, ({ one }) => ({
  card: one(card, { fields: [printingPriceCurrent.cardId], references: [card.id] }),
}));

// ────────────────────────────────────────────────────────────────────────────
// Types
// ────────────────────────────────────────────────────────────────────────────

export type Game = typeof game.$inferSelect;
export type CardSet = typeof cardSet.$inferSelect;
export type Card = typeof card.$inferSelect;
export type NewCard = typeof card.$inferInsert;
export type CardVariant = typeof cardVariant.$inferSelect;
export type NewCardVariant = typeof cardVariant.$inferInsert;
export type CardCondition = (typeof cardCondition.enumValues)[number];
export type ApiSource = (typeof apiSource.enumValues)[number];
